mapper.select:
SELECT a.busiType, a.subjectName, a.busiTypeCode, a.subjectNameCode, to_char(a.HAPPEN_DATE,'yyyy-MM-dd') as happenDate, a.ccy, a.ccy as ccyCode, a.cdFlag, a.cdFlag as cdFlagCode, a.happenAmt, a.dAmt, '' as balFlag, '' as balFlagCode, '' as oAmt, a.cAmt FROM ( /*** 1.1 投资收益分配-已实现未分配损益(借方)**/ select '01' as busiType,/**业务类别**/ '01' as subjectName,/**科目名称**/ '01' as busiTypeCode,/**业务类别code**/ '01' as subjectNameCode,/**科目名称code**/ '1' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'D' as cdFlag,/**借贷方向**/ sum(vod.HAPPEN_AMT) as happenAmt, sum(vod.HAPPEN_AMT) as dAmt,/**借方金额**/ 0 as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'C' and vod.TABLE_ID in ('8004','8012','8032','8103','8105','0') and vod.SUBJECT_NO in ('22320101','22060101','22060201') and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY
union all
/** 1.2 投资收益分配-应付客户收益(贷方)**/ select '01' as busiType,/**业务类别**/ '02' as subjectName,/**科目名称**/ '01' as busiTypeCode,/**业务类别code**/ '02' as subjectNameCode,/**科目名称code**/ '2' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'C' as cdFlag,/**借贷方向**/ nvl(sum(vod.HAPPEN_AMT),0) as happenAmt, 0 as dAmt,/**借方金额**/ nvl(sum(vod.HAPPEN_AMT),0) as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'C' and vod.TABLE_ID in ('8004','8012','8032','0') and vod.SUBJECT_NO = '22320101' and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY
union all
/** 1.3 投资收益分配-管理费收入(贷方)**/ select '01' as busiType,/**业务类别**/ '03' as subjectName,/**科目名称**/ '01' as busiTypeCode,/**业务类别code**/ '03' as subjectNameCode,/**科目名称code**/ '3' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'C' as cdFlag,/**借贷方向**/ nvl(sum(vod.HAPPEN_AMT),0) as happenAmt, 0 as dAmt,/**借方金额**/ nvl(sum(vod.HAPPEN_AMT),0) as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'C' and vod.TABLE_ID in ('8103','8105','0') and vod.SUBJECT_NO in('22060101','22060201') and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY
union all
/** 2.1 兑付客户收益-应付客户收益(借方)**/ select '02' as busiType,/**业务类别**/ '02' as subjectName,/**科目名称**/ '02' as busiTypeCode,/**业务类别code**/ '02' as subjectNameCode,/**科目名称code**/ '4' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'D' as cdFlag,/**借贷方向**/ nvl(sum(vod.HAPPEN_AMT),0) as happenAmt, nvl(sum(vod.HAPPEN_AMT),0) as dAmt,/**借方金额**/ 0 as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'D' and vod.TABLE_ID in ('8005','8013','8014','8033','8037','0') and vod.SUBJECT_NO = '22320101' and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY
union all
/** 2.2 兑付客户收益-存放托管行资金(贷方)**/ select '02' as busiType,/**业务类别**/ '04' as subjectName,/**科目名称**/ '02' as busiTypeCode,/**业务类别code**/ '04' as subjectNameCode,/**科目名称code**/ '5' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'C' as cdFlag,/**借贷方向**/ nvl(sum(vod.HAPPEN_AMT),0) as happenAmt, 0 as dAmt,/**借方金额**/ nvl(sum(vod.HAPPEN_AMT),0) as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'D' and vod.TABLE_ID in ('8005','8013','8014','8033','8037','0') and vod.SUBJECT_NO = '22320101' and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY
union all
/** 3.1 兑付管理费-存放中央款项(借方)**/ select '03' as busiType,/**业务类别**/ '05' as subjectName,/**科目名称**/ '03' as busiTypeCode,/**业务类别code**/ '05' as subjectNameCode,/**科目名称code**/ '6' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'D' as cdFlag,/**借贷方向**/ nvl(sum(vod.HAPPEN_AMT),0) as happenAmt, nvl(sum(vod.HAPPEN_AMT),0) as dAmt,/**借方金额**/ 0 as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'D' and vod.TABLE_ID in ('8104','8106','0') and vod.SUBJECT_NO in ('22060101','22060201') and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY
union all
/** 3.2 兑付管理费-存放托管行资金(贷方)**/ select '03' as busiType,/**业务类别**/ '04' as subjectName,/**科目名称**/ '03' as busiTypeCode,/**业务类别code**/ '04' as subjectNameCode,/**科目名称code**/ '7' orderNum,/**排序号**/ vod.HAPPEN_DATE,/**发生日**/ vod.CCY as ccy,/**币种**/ 'C' as cdFlag,/**借贷方向**/ nvl(sum(vod.HAPPEN_AMT),0) as happenAmt, 0 as dAmt,/**借方金额**/ nvl(sum(vod.HAPPEN_AMT),0) as cAmt/**贷方金额**/ from BOK_VOUCH_DETAIL vod where vod.CD_FLAG = 'D' and vod.TABLE_ID in ('8104','8106','0') and vod.SUBJECT_NO in ('22060101','22060201') and vod.HAPPEN_DATE >= to_date(#{selectDateBegin},'yyyy-mm-dd') and vod.HAPPEN_DATE <= to_date(#{selectDateEnd},'yyyy-mm-dd') group by vod.HAPPEN_DATE,vod.CCY ) a where 1=1
and a.busiTypeCode in
#{busiType}
and a.subjectNameCode in
#{subjectName}
ORDER BY a.HAPPEN_DATE asc ,a.orderNum asc

select (case when (SUM(bal.O_C_AMT)-sum(bal.O_D_AMT)) >= 0 then 'C' ELSE 'D' END) as balFlagCode,/**余额方向**/ abs(SUM(bal.O_C_AMT)-sum(bal.O_D_AMT)) as oAmt /**原币余额：贷方和-借方和**/ from BOK_BALANCE bal where bal.SUBJECT_NO in
#{subjectNo}
and bal.BALANCE_DATE = to_date(#{happenDate},'yyyy-mm-dd')
